class MyWidget extends StatefulWidget {
  @override
  State<MyWidget> createState() => _MyWidgetState();
}

class _MyWidgetState extends State<MyWidget> with AfterInitMixin<MyWidget> {
  late Size size;
  @override
  void didInitState() {
    size = MediaQuery.of(context).size;
  }
  @override
  Widget build(BuildContext context) => Center(child: Text(size.toString()));
}
